#!/usr/bin/env python3
"""Slides-only generated-output agreement, purge planning and edge verification."""
import argparse
from collections import namedtuple
from concurrent.futures import ThreadPoolExecutor
import hashlib
import http.client
import json
from pathlib import Path
import random
import re
import subprocess
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

BASE = "https://products.aspose.com/slides/"
Observation = namedtuple("Observation", "status actual_bytes cache server declared_bytes error")


def validate_url(url):
    parsed = urllib.parse.urlsplit(url)
    decoded = parsed.path
    for _ in range(5):
        value = urllib.parse.unquote(decoded)
        if value == decoded:
            break
        decoded = value
    if (parsed.scheme != "https" or parsed.netloc != "products.aspose.com"
            or not parsed.path.startswith("/slides/") or parsed.query or parsed.fragment
            or any(c.isspace() for c in url) or "\\" in decoded or "*" in decoded
            or "//" in decoded or any(part in (".", "..") for part in decoded.split("/"))):
        raise ValueError(f"URL is outside the exact Slides scope: {url!r}")


def read_expectations(paths):
    result = {}
    for path in paths:
        for number, line in enumerate(Path(path).read_text(encoding="utf-8").splitlines(), 1):
            fields = line.split("\t")
            if len(fields) != 2 or not re.fullmatch(r"[0-9]+", fields[1]):
                raise ValueError(f"invalid changed row: {path}:{number}")
            url, size = fields[0], int(fields[1])
            validate_url(url)
            if url in result and result[url] != size:
                raise ValueError(f"conflicting generated byte lengths for {url}: {result[url]} and {size}")
            result[url] = size
    if not result:
        raise ValueError("no uploaded URLs: nothing to purge or verify")
    return dict(sorted(result.items()))


def snapshot(root, language, languages, source_sha, output):
    root = Path(root)
    if (language == "en" or language not in languages or "en" not in languages
            or any(not re.fullmatch(r"[a-z]{2}(?:-[a-z]+)?", value) for value in languages)
            or not re.fullmatch(r"[0-9a-f]{40}", source_sha)):
        raise ValueError("invalid language inventory or pinned source SHA")
    entries = {}
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise ValueError(f"generated symlink cannot be published: {path}")
        if not path.is_file() or path.name == ".gitignore":
            continue
        key = path.relative_to(root).as_posix()
        if any(c.isspace() for c in key) or "\\" in key:
            raise ValueError(f"invalid generated key: {key!r}")
        top = key.split("/", 1)[0]
        if top in languages and top != "en":
            if top != language:
                raise ValueError(f"unexpected generated locale {top} in {language} build")
            continue
        data = path.read_bytes()
        entries[key] = {"bytes": len(data), "sha256": hashlib.sha256(data).hexdigest()}
    if not entries:
        raise ValueError("English/shared inventory is empty")
    document = {"language": language, "languages": sorted(languages), "source_sha": source_sha, "files": entries}
    Path(output).parent.mkdir(parents=True, exist_ok=True)
    Path(output).write_text(json.dumps(document, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return document


def compare(paths, expected_languages, source_sha):
    documents = [json.loads(Path(path).read_text(encoding="utf-8")) for path in paths]
    actual = [document["language"] for document in documents]
    if sorted(actual) != sorted(expected_languages) or len(actual) != len(set(actual)):
        raise ValueError(f"missing, duplicate or unexpected build manifests: expected {sorted(expected_languages)}, got {sorted(actual)}")
    reference = documents[0]
    for document in documents:
        if (document["source_sha"] != source_sha
                or document["languages"] != sorted(["en"] + expected_languages)):
            raise ValueError("builds used different source refs or language inventories")
        keys = sorted(set(reference["files"]) | set(document["files"]))
        differences = [key for key in keys if reference["files"].get(key) != document["files"].get(key)]
        if differences:
            raise ValueError(f"English/shared output differs in {document['language']}: {', '.join(differences[:20])}")
    return len(reference["files"])


def plan(changed, output, shard_size):
    rows = read_expectations(sorted(Path(changed).glob("*.tsv")))
    output = Path(output)
    (output / "shards").mkdir(parents=True, exist_ok=True)
    (output / "all.tsv").write_text("".join(f"{url}\t{size}\n" for url, size in rows.items()), encoding="utf-8")
    urls = list(rows)
    if shard_size < 1:
        raise ValueError("shard size must be positive")
    for number, start in enumerate(range(0, len(urls), shard_size)):
        (output / "shards" / f"{number:03}.txt").write_text("\n".join(urls[start:start + shard_size]) + "\n", encoding="utf-8")
    html = [url for url in urls if url.endswith("/")]
    canaries = set()
    if html:
        canaries.update((min(html, key=lambda u: (u.count("/"), u)), max(html, key=lambda u: (u.count("/"), u))))
    for pattern in (r"/slides/[a-z]{2}(?:-[a-z]+)?/", r"/index\.md$", r"/llms\.txt$", r"/slides/(?:css|js)/", r"/sitemap\.xml$"):
        match = next((url for url in urls if re.search(pattern, url)), None)
        if match:
            canaries.add(match)
    (output / "canaries.txt").write_text("\n".join(sorted(canaries)) + ("\n" if canaries else ""), encoding="utf-8")
    return len(rows)


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def edge(url, expected_bytes=None):
    validate_url(url)
    request = urllib.request.Request(url, headers={"Accept-Encoding": "identity", "User-Agent": "slides-production/purge-canary"})
    try:
        response = urllib.request.build_opener(NoRedirect()).open(request, timeout=30)
    except urllib.error.HTTPError as error:
        response = error
    except (OSError, urllib.error.URLError):
        return Observation(0, None, "", "", None, "request_failed")
    with response:
        length = response.headers.get("Content-Length", "")
        declared = int(length) if length.isdigit() else None
        actual = 0
        error = "" if declared is not None else "missing_or_invalid_content_length"
        # Verification reads at most the expected body plus one byte: an oversized
        # response cannot force an unbounded download. Direct diagnostic calls use
        # the declared length, capped to the same conservative fallback.
        limit = expected_bytes + 1 if expected_bytes is not None else min((declared or 0) + 1, 64 * 1024 * 1024)
        if expected_bytes is None and declared is None:
            limit = 64 * 1024 * 1024
        try:
            while actual < limit:
                chunk = response.read(min(65536, limit - actual))
                if not chunk:
                    break
                actual += len(chunk)
        except http.client.IncompleteRead as failure:
            actual += len(failure.partial)
            error = "truncated_body"
        except (OSError, http.client.HTTPException):
            error = "body_read_failed"
        if declared is not None and actual != declared:
            error = error or "body_length_differs_from_header"
        if expected_bytes is not None and actual > expected_bytes:
            error = "body_exceeds_expectation"
        return Observation(response.code, actual, response.headers.get("CDN-Cache", ""),
                           response.headers.get("Server", ""), declared, error)


def verify(expectations, canaries, report, probe=edge, sample_size=50, floor=95,
           settle_seconds=0, retry=None):
    if not expectations or sample_size < 1 or not 0 <= floor <= 100:
        raise ValueError("invalid verification expectations or sample settings")
    for url in expectations:
        validate_url(url)
    if any(url not in expectations for url in canaries):
        raise ValueError("canary is missing a generated expectation")
    report = Path(report)
    report.mkdir(parents=True, exist_ok=True)
    sample = random.SystemRandom().sample(sorted(expectations), min(sample_size, len(expectations)))
    watch = sorted(set(canaries) | set(sample))
    (report / "watch.txt").write_text("\n".join(watch) + "\n", encoding="utf-8")
    outcomes = {}
    with (report / "observations.tsv").open("w", encoding="utf-8", newline="") as out:
        out.write("url\tstatus\texpected_bytes\tactual_bytes\tresult\tcache\tserver\tattempt\tdeclared_bytes\terror\n")
        out.flush()
        if settle_seconds:
            time.sleep(settle_seconds)
        for attempt in (1, 2):
            for url in watch:
                try:
                    observation = edge(url, expectations[url]) if probe is edge else probe(url)
                    if len(observation) == 6:
                        code, length, cache, server, declared, error = observation
                    else:
                        code, length, cache, server = observation
                        declared, error = length, ""
                except Exception:
                    code, length, cache, server = 0, None, "", ""
                    declared, error = None, "probe_failed"
                passed = code == 200 and length == expectations[url] and declared == expectations[url] and not error
                outcomes[url] = passed
                fields = (url, str(code), str(expectations[url]), "" if length is None else str(length), "PASS" if passed else "FAIL", cache, server, str(attempt), "" if declared is None else str(declared), error)
                out.write("\t".join(value.replace("\t", " ").replace("\r", " ").replace("\n", " ") for value in fields) + "\n")
                out.flush()
            bad = [url for url in watch if not outcomes[url]]
            if attempt == 2 or not bad or retry is None:
                break
            retry(bad)
            if settle_seconds:
                time.sleep(settle_seconds)
    failed_canaries = sorted(url for url in canaries if not outcomes[url])
    ok = sum(outcomes.values())
    percent = 100 * ok // len(watch)
    result = {"passed": not failed_canaries and percent >= floor, "checked": len(watch), "ok": ok,
              "percent": percent, "floor": floor, "failed_canaries": failed_canaries, "failed_urls": bad}
    (report / "result.json").write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(f"Edge verified {ok}/{len(watch)} URLs ({percent}%); failed canaries: {len(failed_canaries)}")
    return result["passed"]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    snap = sub.add_parser("snapshot")
    snap.add_argument("--root", required=True); snap.add_argument("--language", required=True)
    snap.add_argument("--languages", required=True); snap.add_argument("--source-sha", required=True)
    snap.add_argument("--output", required=True)
    gate = sub.add_parser("compare")
    gate.add_argument("--manifests", required=True); gate.add_argument("--languages", required=True)
    gate.add_argument("--source-sha", required=True)
    planning = sub.add_parser("plan")
    planning.add_argument("--changed", required=True); planning.add_argument("--output", required=True)
    planning.add_argument("--shard-size", type=int, default=10000)
    planning.add_argument("--github-output")
    verification = sub.add_parser("verify")
    verification.add_argument("--plan", required=True); verification.add_argument("--report", required=True)
    verification.add_argument("--sample-size", type=int, default=50)
    verification.add_argument("--floor", type=int, default=95)
    verification.add_argument("--settle-seconds", type=int, default=25)
    verification.add_argument("--parallel", type=int, default=24)
    args = parser.parse_args()
    try:
        if args.command == "snapshot":
            snapshot(args.root, args.language, json.loads(args.languages), args.source_sha, args.output)
        elif args.command == "compare":
            count = compare(sorted(Path(args.manifests).glob("*.json")), json.loads(args.languages), args.source_sha)
            print(f"All language builds agree on {count} English/shared SHA256 entries")
        elif args.command == "plan":
            print(f"Unique uploaded URLs: {plan(args.changed, args.output, args.shard_size)}")
            if args.github_output:
                shards = sorted(path.stem for path in (Path(args.output) / "shards").glob("*.txt"))
                with Path(args.github_output).open("a", encoding="utf-8") as output:
                    output.write("shards=" + json.dumps(shards) + "\n")
        else:
            directory = Path(args.plan)
            expectations = read_expectations([directory / "all.tsv"])
            canaries = (directory / "canaries.txt").read_text(encoding="utf-8").splitlines()
            def retry(urls):
                def purge(url):
                    return subprocess.run(["bash", str(directory / "purge_one.sh"), url], check=False).returncode
                with ThreadPoolExecutor(max_workers=args.parallel) as pool:
                    list(pool.map(purge, urls))
            if not verify(expectations, canaries, args.report, sample_size=args.sample_size,
                          floor=args.floor, settle_seconds=args.settle_seconds, retry=retry):
                return 1
    except (ValueError, KeyError, OSError, json.JSONDecodeError) as error:
        print(f"::error::{error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
